kernel vec4 maskIntersect(__sample base, __sample child) {
  float value = base.r * child.r;
  return vec4(value, 0.0, 0.0, 1.0);
}

kernel vec4 maskSubtract(__sample base, __sample child) {
  float value = base.r * (1.0 - child.r);
  return vec4(value, 0.0, 0.0, 1.0);
}

#include <metal_stdlib>
using namespace metal;

struct DrawMaskStrokeParams {
  uint stampCount;
  float radius;
  float opacity;
  float softness;
  uint erase;
  uint originX;
  uint originY;
  uint width;
  uint height;
};

kernel void clearMaskTexture(texture2d<float, access::write> mask [[texture(0)]],
                             uint2 gid [[thread_position_in_grid]]) {
  if (gid.x >= mask.get_width() || gid.y >= mask.get_height()) {
    return;
  }
  mask.write(float4(0.0), gid);
}

// Rewrites the texture into the canonical mask layout (coverage in r and a, g/b zero).
// Restored snapshots can arrive as opaque red-channel images (the persisted PNGs), whose
// alpha=1 everywhere would display as a full-canvas tint in the stroke overlay.
kernel void normalizeMaskTexture(texture2d<float, access::read_write> mask [[texture(0)]],
                                 uint2 gid [[thread_position_in_grid]]) {
  if (gid.x >= mask.get_width() || gid.y >= mask.get_height()) {
    return;
  }
  float value = mask.read(gid).r;
  mask.write(float4(value, 0.0, 0.0, value), gid);
}

// Distance from point p to the segment a-b.
inline float distanceToSegment(float2 p, float2 a, float2 b) {
  float2 ab = b - a;
  float denom = max(dot(ab, ab), 1e-5);
  float t = clamp(dot(p - a, ab) / denom, 0.0, 1.0);
  float2 proj = a + t * ab;
  return distance(p, proj);
}

// The stroke is rendered as the signed-distance field of the polyline (a chain of capsules)
// rather than a row of stamped circles. Taking the distance to the nearest *segment* gives a
// perfectly even-width stroke with a smooth edge — overlapping circle stamps scallop the border
// and build up unevenly at the overlaps.
kernel void drawMaskStroke(texture2d<float, access::read_write> mask [[texture(0)]],
                           constant float2 *stamps [[buffer(0)]],
                           constant DrawMaskStrokeParams &params [[buffer(1)]],
                           uint2 gid [[thread_position_in_grid]]) {
  if (gid.x >= params.width || gid.y >= params.height) {
    return;
  }

  uint2 pixel = uint2(gid.x + params.originX, gid.y + params.originY);
  if (pixel.x >= mask.get_width() || pixel.y >= mask.get_height()) {
    return;
  }

  float2 pixelCenter = float2(float(pixel.x) + 0.5, float(pixel.y) + 0.5);
  float radius = max(params.radius, 0.5);

  float minDist = radius + 1.0;
  if (params.stampCount == 1) {
    minDist = distance(pixelCenter, stamps[0]);
  } else {
    for (uint i = 0; i + 1 < params.stampCount; i++) {
      minDist = min(minDist, distanceToSegment(pixelCenter, stamps[i], stamps[i + 1]));
    }
  }

  if (minDist > radius) {
    return;
  }

  // Hard core out to `inner`, then a smoothstep feather from `inner` to the edge. `softness` is
  // the fraction of the radius given over to the feather (0 = hard, 1 = feather the whole brush).
  // Cap `inner` a pixel inside the edge so a fully hard brush still gets a 1px
  // antialiasing ramp instead of a stair-stepped border.
  float inner = min(radius * (1.0 - params.softness), radius - 1.0);
  float featherRange = max(radius - inner, 0.01);
  float coverage = 1.0;
  if (minDist > inner) {
    float t = clamp((minDist - inner) / featherRange, 0.0, 1.0);
    coverage = 1.0 - (t * t * (3.0 - 2.0 * t));
  }

  if (coverage <= 0.0) {
    return;
  }

  float existing = mask.read(pixel).r;
  float amount = clamp(coverage * params.opacity, 0.0, 1.0);
  float value = params.erase == 1
    ? max(0.0, existing - amount)
    : max(existing, amount);

  mask.write(float4(value, 0.0, 0.0, value), pixel);
}
